<?php
declare(strict_types=1);

namespace App\Application\Services;

use App\Application\Exceptions\{EntityNotFound, OperationConflict};
use App\Application\Repositories\CatalogRepository;
use App\Core\Persistence\TransactionManager;
use App\Domain\Catalog\{Brand, CatalogRules, Category, Product, ProductVariant, Unit};

final class CatalogManagementService
{
    public function __construct(private readonly CatalogRepository $catalog, private readonly TransactionManager $transactions) {}

    public function createCategory(Category $category, array $attributes=[], ?callable $audit=null): Category { return $this->transactions->transaction(function()use($category,$attributes,$audit){ if($category->parentId!==null)$this->catalog->categoryAncestorIds($category->parentId);$created=$this->catalog->createCategory($category);$this->catalog->replaceCategoryAttributes($created->id??0,$attributes);if($audit)$audit($created);return $created;}); }
    public function updateCategory(int $id, Category $changes, array $attributes=[], ?callable $audit=null): Category { return $this->transactions->transaction(function()use($id,$changes,$attributes,$audit){$current=$this->catalog->findCategory($id,true)??throw new EntityNotFound('La categoría no existe.');if(!hash_equals($current->code,$changes->code))throw new OperationConflict('La clave de la categoría no puede cambiar.');$ancestors=$this->catalog->categoryAncestorIds($changes->parentId);if(in_array($id,$ancestors,true))throw new OperationConflict('La categoría superior produciría una relación circular.');$updated=$current->withDetails($changes->name,$changes->description,$changes->parentId);$this->catalog->updateCategory($updated);$this->catalog->replaceCategoryAttributes($id,$attributes);if($audit)$audit($updated);return $updated;}); }
    public function setCategoryActive(int $id,bool $active,?callable $audit=null): Category { return $this->status($id,$active,fn($id)=>$this->catalog->findCategory($id,true),fn($id,$a)=>$this->catalog->setCategoryActive($id,$a),$audit); }
    public function createBrand(Brand $brand,?callable $audit=null): Brand { return $this->create($brand,fn($v)=>$this->catalog->createBrand($v),$audit); }
    public function updateBrand(int $id,Brand $changes,?callable $audit=null): Brand { return $this->transactions->transaction(function()use($id,$changes,$audit){$current=$this->catalog->findBrand($id,true)??throw new EntityNotFound('La marca no existe.');if(!hash_equals($current->code,$changes->code))throw new OperationConflict('La clave de la marca no puede cambiar.');$updated=$current->withDetails($changes->name,$changes->description);$this->catalog->updateBrand($updated);if($audit)$audit($updated);return $updated;}); }
    public function setBrandActive(int $id,bool $active,?callable $audit=null): Brand { return $this->status($id,$active,fn($id)=>$this->catalog->findBrand($id,true),fn($id,$a)=>$this->catalog->setBrandActive($id,$a),$audit); }
    public function createUnit(Unit $unit,?callable $audit=null): Unit { return $this->create($unit,fn($v)=>$this->catalog->createUnit($v),$audit); }
    public function updateUnit(int $id,Unit $changes,?callable $audit=null): Unit { return $this->transactions->transaction(function()use($id,$changes,$audit){$current=$this->catalog->findUnit($id,true)??throw new EntityNotFound('La unidad no existe.');if(!hash_equals($current->code,$changes->code))throw new OperationConflict('La clave de la unidad no puede cambiar.');if($current->decimalPlaces!==$changes->decimalPlaces&&$this->catalog->unitHasVariants($id))throw new OperationConflict('La precisión no puede cambiar porque la unidad ya está asociada a variantes.');$updated=$current->withDetails($changes->name,$changes->symbol,$changes->decimalPlaces);$this->catalog->updateUnit($updated);if($audit)$audit($updated);return $updated;}); }
    public function setUnitActive(int $id,bool $active,?callable $audit=null): Unit { return $this->status($id,$active,fn($id)=>$this->catalog->findUnit($id,true),fn($id,$a)=>$this->catalog->setUnitActive($id,$a),$audit); }
    public function createProduct(Product $product, ProductVariant $variant, array $barcodes, ?callable $audit=null): Product
    {
        return $this->transactions->transaction(function()use($product,$variant,$barcodes,$audit){$created=$this->catalog->createProduct($product);$createdVariant=$this->catalog->createVariant(ProductVariant::create($created->id??0,$variant->unitId,$variant->sku,$variant->name));foreach(array_values(array_unique(array_filter(array_map('trim',$barcodes)))) as $i=>$barcode)$this->catalog->addBarcode($createdVariant->id??0,CatalogRules::barcode($barcode),$i===0);if($audit)$audit($created);return $created;});
    }
    public function updateProduct(int $id,Product $changes,?callable $audit=null): Product { return $this->transactions->transaction(function()use($id,$changes,$audit){$current=$this->catalog->findProduct($id,true)??throw new EntityNotFound('El producto no existe.');if(!hash_equals($current->code,$changes->code))throw new OperationConflict('La clave del producto no puede cambiar.');$updated=$current->withDetails($changes->name,$changes->description,$changes->categoryId,$changes->brandId,$changes->tracksLots,$changes->tracksExpiration,$changes->tracksSerials);$this->catalog->updateProduct($updated);if($audit)$audit($updated);return $updated;}); }
    public function setProductActive(int $id,bool $active,?callable $audit=null): Product { return $this->status($id,$active,fn($id)=>$this->catalog->findProduct($id,true),fn($id,$a)=>$this->catalog->setProductActive($id,$a),$audit); }
    public function createVariant(ProductVariant $variant,array $barcodes,?callable $audit=null): ProductVariant { return $this->transactions->transaction(function()use($variant,$barcodes,$audit){if($this->catalog->findProduct($variant->productId,true)===null)throw new EntityNotFound('El producto no existe.');$created=$this->catalog->createVariant($variant);foreach(array_values(array_unique(array_filter(array_map('trim',$barcodes)))) as $i=>$barcode)$this->catalog->addBarcode($created->id??0,CatalogRules::barcode($barcode),$i===0);if($audit)$audit($created);return $created;}); }
    public function updateVariant(int $id,int $productId,int $unitId,string $name,?callable $audit=null): ProductVariant { return $this->transactions->transaction(function()use($id,$productId,$unitId,$name,$audit){$current=$this->catalog->findVariant($id,true)??throw new EntityNotFound('La variante no existe.');if($current->productId!==$productId)throw new OperationConflict('La variante no pertenece al producto indicado.');$updated=$current->withDetails($unitId,$name);$this->catalog->updateVariant($updated);if($audit)$audit($updated);return $updated;}); }
    public function setVariantActive(int $id,int $productId,bool $active,?callable $audit=null): ProductVariant { return $this->transactions->transaction(function()use($id,$productId,$active,$audit){$current=$this->catalog->findVariant($id,true)??throw new EntityNotFound('La variante no existe.');if($current->productId!==$productId)throw new OperationConflict('La variante no pertenece al producto indicado.');$this->catalog->setVariantActive($id,$active);$updated=$current->withActive($active);if($audit)$audit($updated);return $updated;}); }
    public function addBarcode(int $variantId,int $productId,string $barcode,bool $primary,?callable $audit=null): int { return $this->transactions->transaction(function()use($variantId,$productId,$barcode,$primary,$audit){$variant=$this->catalog->findVariant($variantId,true)??throw new EntityNotFound('La variante no existe.');if($variant->productId!==$productId)throw new OperationConflict('La variante no pertenece al producto indicado.');$id=$this->catalog->addBarcode($variantId,CatalogRules::barcode($barcode),$primary);if($audit)$audit($id);return $id;}); }
    public function removeBarcode(int $barcodeId,int $variantId,int $productId,?callable $audit=null): void { $this->transactions->transaction(function()use($barcodeId,$variantId,$productId,$audit){$variant=$this->catalog->findVariant($variantId,true)??throw new EntityNotFound('La variante no existe.');if($variant->productId!==$productId)throw new OperationConflict('La variante no pertenece al producto indicado.');$this->catalog->removeBarcode($barcodeId,$variantId);if($audit)$audit($barcodeId);}); }
    public function addConversion(int $variantId,int $productId,int $fromUnitId,int $toUnitId,string $factor,?callable $audit=null): int { return $this->transactions->transaction(function()use($variantId,$productId,$fromUnitId,$toUnitId,$factor,$audit){$variant=$this->catalog->findVariant($variantId,true)??throw new EntityNotFound('La variante no existe.');if($variant->productId!==$productId)throw new OperationConflict('La variante no pertenece al producto indicado.');$id=$this->catalog->addConversion($variantId,$fromUnitId,$toUnitId,trim($factor));if($audit)$audit($id);return $id;}); }
    public function removeConversion(int $conversionId,int $variantId,int $productId,?callable $audit=null): void { $this->transactions->transaction(function()use($conversionId,$variantId,$productId,$audit){$variant=$this->catalog->findVariant($variantId,true)??throw new EntityNotFound('La variante no existe.');if($variant->productId!==$productId)throw new OperationConflict('La variante no pertenece al producto indicado.');$this->catalog->removeConversion($conversionId,$variantId);if($audit)$audit($conversionId);}); }
    public function replaceVariantAttributes(int $variantId,int $productId,array $values,?callable $audit=null): void { $this->transactions->transaction(function()use($variantId,$productId,$values,$audit){$variant=$this->catalog->findVariant($variantId,true)??throw new EntityNotFound('La variante no existe.');if($variant->productId!==$productId)throw new OperationConflict('La variante no pertenece al producto indicado.');$this->catalog->replaceVariantAttributes($variantId,$values);if($audit)$audit($variantId);}); }
    private function create(object $value,callable $writer,?callable $audit): object { return $this->transactions->transaction(function()use($value,$writer,$audit){$created=$writer($value);if($audit)$audit($created);return $created;}); }
    private function status(int $id,bool $active,callable $reader,callable $writer,?callable $audit): object { return $this->transactions->transaction(function()use($id,$active,$reader,$writer,$audit){$entity=$reader($id)??throw new EntityNotFound('El registro no existe.');$writer($id,$active);$updated=$entity->withActive($active);if($audit)$audit($updated);return $updated;}); }
}
